      "$type": "color",
      "$description": "Paper — Inverse surface, card backgrounds on darker sections, button text on filled putty buttons, hairline border against putty canvas"
    },
    "carbon": {
      "$value": "#191919",
      "$type": "color",
      "$description": "Carbon — Secondary dark surface for feature sections and inverted blocks — softer than pure ink, used where a dark band needs to feel like printed stock rather than a screen"
    },
